export function slugify(value: string, options: SlugOptions = {}): string {
	// 1. Normalize to NFD so diacritics separate from base chars
	let slug = value.normalize("NFD");

	// 2. Remove combining diacritical marks (category Mn/Mc)
	slug = slug.replace(/\p{Mn}/gu, "");

	// 3. Lowercase
	slug = slug.toLocaleLowerCase();

	// 4. Replace any non-alphanumeric character with a hyphen
	slug = slug.replace(/[^a-z0-9]+/g, "-");

	// 5. Trim leading/trailing hyphens
	slug = slug.replace(/^-|-$/g, "");

	// 6. Truncate at word boundary respecting maxLength
	if (options.maxLength != null && options.maxLength > 0 && slug.length > options.maxLength) {
		slug = slug.slice(0, options.maxLength);
		// Trim off any trailing hyphen
		slug = slug.replace(/-+$/g, "");
	}

	return slug;
}

